     */
    'user_agent' => 'Static Maps API/ github.com/dshanske/Static-Maps-API-PHP',

    /*
     * Who may draw which maps (#28).
     *
     * 'mode'          'open' (default): anyone may draw free maps. Maps whose
     *                 tiles use a provider key set below (in `providers`),
